+import type { ChildProcess } from "node:child_process";
+import { EventEmitter } from "node:events";
+import { existsSync, mkdirSync } from "node:fs";
+import { createRequire } from "node:module";
+import { Socket } from "node:net";
+import { homedir, tmpdir } from "node:os";
+import { dirname, join } from "node:path";
+import { PassThrough, type Readable, type Writable } from "node:stream";
+import { pathToFileURL } from "node:url";
+
+interface FilesystemFragment {
+	readonlyPaths: string[];
+	readwritePaths: string[];
+}
+
+interface MxcProcess {
+	readonly standardInput: Writable | null;
+	readonly standardOutput: Readable | null;
+	readonly standardError: Readable | null;
+	wait(): Promise<{ exitCode: number; timedOut: boolean }>;
+	kill(): void;
+	dispose(): void;
+}
+
+interface MxcModule {
+	spawn(request: Record<string, unknown>): Promise<MxcProcess>;
+	policy: {
+		filesystem: {
+			getAvailableToolsPolicy(): FilesystemFragment;
+			getUserProfilePolicy(): FilesystemFragment;
+		};
+	};
+}
+
+export const PROJECT_SANDBOX_SETTING_LABEL =
+	"Only allow edits in project directory";
+
+const MXC_SDK_DIR_ENV = "CLINE_MXC_SDK_DIR";
+
+/**
+ * Package manager caches that installs and builds need to write. Each is
+ * created up front when the directory holding it exists (the tool is
+ * installed), because the sandbox would leave that parent read-only and a
+ * first install or build could not create it.
+ */
+const HOME_CACHE_DIRS = [
+	".npm",
+	".cache",
+	".bun/install/cache",
+	".cargo/registry",
+	".cargo/git",
+	"go/pkg/mod",
+	".m2/repository",
+	".nuget/packages",
+	"Library/Caches",
+	"Library/pnpm/store",
+];
+/** Granted only when present, since their parent is just the home directory. */
+const EXISTING_HOME_CACHE_DIRS = [
+	".gradle",
+	".pnpm-store",
+	".local/share/pnpm",
+];
+const LOCAL_APP_DATA_CACHE_DIRS = ["npm-cache"];
+const EXISTING_LOCAL_APP_DATA_CACHE_DIRS = ["pip", "Yarn", "pnpm-cache"];
+
+function ensureCacheDirs(dirs: string[]): string[] {
+	for (const dir of dirs) {
+		if (!existsSync(dir) && existsSync(dirname(dir))) {
+			try {
+				mkdirSync(dir, { recursive: true });
+			} catch {
+				// Ungranted caches only fail the tools that need them.
+			}
+		}
+	}
+	return dirs;
+}
+
+function cliPlatformPackageDir(): string | undefined {
+	// The npm wrapper hard-links the platform binary into its own bin/, so
+	// resolve the platform package that ships the runtime from the wrapper.
+	const wrapperPath = process.env.CLINE_WRAPPER_PATH?.trim();
+	if (!wrapperPath) {
+		return undefined;
+	}
+	const platform = process.platform === "win32" ? "windows" : process.platform;
+	try {
+		return dirname(
+			createRequire(wrapperPath).resolve(
+				`@cline/cli-${platform}-${process.arch}/package.json`,
+			),
+		);
+	} catch {
+		return undefined;
+	}
+}
